package com.southstand.football.matchdata;
import static org.assertj.core.api.Assertions.assertThat;import java.util.List;import java.util.Map;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;
@SpringBootTest class T17RosterExpansionTests{@Autowired JdbcTemplate jdbc;
 @Test void selectedTeamsHaveEighteenPlayersAndRequiredPositions(){List<Map<String,Object>> rows=jdbc.queryForList("SELECT r.season_id,r.team_id,COUNT(*) total,SUM(r.position='GOALKEEPER') gk,SUM(r.position='DEFENDER') df,SUM(r.position='MIDFIELDER') mf,SUM(r.position='FORWARD') fw FROM football_team_season_player r WHERE EXISTS(SELECT 1 FROM football_match_lineup l JOIN match_info m ON m.id=l.match_id JOIN football_season s ON s.league_id=m.league_id AND s.current_flag=1 WHERE l.team_id=r.team_id AND s.id=r.season_id AND l.is_deleted=0) AND r.status='ACTIVE' AND r.is_deleted=0 GROUP BY r.season_id,r.team_id");assertThat(rows).hasSize(9);assertThat(rows).allSatisfy(x->{assertThat(((Number)x.get("total")).intValue()).isGreaterThanOrEqualTo(18);assertThat(((Number)x.get("gk")).intValue()).isGreaterThanOrEqualTo(2);assertThat(((Number)x.get("df")).intValue()).isGreaterThanOrEqualTo(5);assertThat(((Number)x.get("mf")).intValue()).isGreaterThanOrEqualTo(5);assertThat(((Number)x.get("fw")).intValue()).isGreaterThanOrEqualTo(3);});}
 @Test void newPlayersHaveFiveLayerRelations(){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM football_player p JOIN team_player tp ON tp.player_id=p.id AND tp.status='ACTIVE' AND tp.is_deleted=0 JOIN football_team_season_player r ON r.player_id=p.id AND r.team_id=tp.team_id AND r.status='ACTIVE' AND r.is_deleted=0 JOIN football_player_team_history h ON h.player_id=p.id AND h.team_id=tp.team_id AND h.current_flag=1 AND h.is_deleted=0 JOIN football_player_competition_stat ps ON ps.player_id=p.id AND ps.team_id=tp.team_id AND ps.season_id=r.season_id AND ps.is_deleted=0 WHERE p.id>=33000000000000001 AND p.id<33100000000000001 AND p.is_deleted=0",Integer.class);assertThat(n).isEqualTo(108);}}
